// Oeste Tag — Huntington theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with arbitrary values, JSX transform.
// Requires Huntington tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/huntington/src/index.js
// Docs: https://oeste.hiddeninwest.com/huntington/#/components/tag

export function Tag({ children }) {
  return (
    <span className="inline-flex rounded-full border border-[var(--color-border)] px-[10px] py-1 text-[var(--type-tag-size)] leading-[var(--type-tag-leading)] tracking-[var(--type-tag-tracking)] text-[var(--color-muted)] [font-weight:var(--type-tag-weight)] uppercase">{children}</span>
  );
}
